/// <summary>
/// PaffH 22.11.21
/// set NameAlias before saving
/// </summary>
/// <param name="sender">DirPartyTable</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(DirPartyTable), DataEventType::Updating),
    SuppressBPWarning('BPParameterNotUsed',"'e' is not used")]
public static void DirPartyTable_onUpdating(Common sender, DataEventArgs e)
{
    DirPartyTable dirPartyTable = sender as DirPartyTable;
    NDXDirPartyTableBaseType::CreateInstance(dirPartyTable).setNameAlias();
}

/// <summary>
/// PaffH 23.11.21
/// </summary>
/// <param name="original">DirPartyTable</param>
/// <param name="updated">DirPartyTable</param>
[SubscribesTo(tableStr(DirPartyTable), delegateStr(DirPartyTable, dirPartyInserting))]
public static void DirPartyTable_dirPartyInserting(DirPartyTable original, DirPartyTable updated)
{
    NDXDirPartyTableBaseType::findDirPartyInfo(updated.PartyNumber, NDXDirPartyInfo::construct(true));
}
